3	import (
4		"context"
5		"encoding/json"
6		"fmt"
7		"time"
8	
9		"github.com/integrio-intropy/intropy-cli/internal/skill"
10		"github.com/integrio-intropy/intropy-cli/internal/skill/oci"
11		"github.com/spf13/cobra"
12	)
13	
14	type skillsCollectionAddFlags struct {
15		name   string
16		ref    string
17		output string
18	}
19	
20	var skillsCollectionAddOpts skillsCollectionAddFlags
21	
22	var skillsCollectionAddCmd = &cobra.Command{
23		Use:   "add",
24		Short: "Register a collection to this project",
25		Long: `Adds a collection registration to skills.json and caches the
26	collection's index for offline name lookups. The collection must already be
27	published to an OCI registry. After registration, skills can be installed by
28	name via 'intropy skills add --name <skill-name>'.`,
29		Args: cobra.NoArgs,
30		RunE: func(cmd *cobra.Command, args []string) error {
31			if err := validateOutputFlag(skillsCollectionAddOpts.output, "json", "plain"); err != nil {
32				return err
33			}
34			if skillsCollectionAddOpts.name == "" {
35				return fmt.Errorf("collection add: --name is required")
36			}
37			if skillsCollectionAddOpts.ref == "" {
38				return fmt.Errorf("collection add: --ref is required")
39			}
40	
41			if _, err := oci.ParseReference(skillsCollectionAddOpts.ref); err != nil {
42				return fmt.Errorf("collection add: invalid ref %q: %w", skillsCollectionAddOpts.ref, err)
43			}
44	
45			project, err := resolveOrBootstrapProject(".")
46			if err != nil {
47				return fmt.Errorf("collection add: %w", err)
48			}
49	
50			manifest, err := project.LoadManifest()
51			if err != nil {
52				return fmt.Errorf("collection add: load manifest: %w", err)
53			}
54	
55			for _, c := range manifest.Collections {
56				if c.Name == skillsCollectionAddOpts.name {
57					return fmt.Errorf("collection add: %q is already registered (ref: %s)",
58						skillsCollectionAddOpts.name, c.Ref)
59				}
60			}
61	
62			client, err := oci.NewClient()
63			if err != nil {
64				return fmt.Errorf("collection add: %w", err)
65			}
66	
67			// Fetch and cache the index up-front. If the registry rejects the
68			// ref we'd rather fail before mutating skills.json.
69			ctx := cmd.Context()
70			if ctx == nil {
71				ctx = context.Background()
72			}
73			index, err := client.PullIndex(ctx, skillsCollectionAddOpts.ref)
74			if err != nil {
75				return fmt.Errorf("collection add: fetch index: %w", err)
76			}
77			cached := &skill.CachedCollection{
78				Ref:       skillsCollectionAddOpts.ref,
79				FetchedAt: time.Now().UTC(),
80				Index:     index,
81			}
82			if err := project.SaveCollectionCache(skillsCollectionAddOpts.name, cached); err != nil {
83				return fmt.Errorf("collection add: cache index: %w", err)
84			}
85	
86			manifest.Collections = append(manifest.Collections, skill.ManifestCollection{
87				Name: skillsCollectionAddOpts.name,
88				Ref:  skillsCollectionAddOpts.ref,
89			})
90	
91			if err := project.SaveManifest(manifest); err != nil {
92				return fmt.Errorf("collection add: %w", err)
93			}
94			if skillsCollectionAddOpts.output == "json" {
95				enc := json.NewEncoder(cmd.OutOrStdout())
96				enc.SetIndent("", "  ")
97				return enc.Encode(map[string]any{
98					"name":         skillsCollectionAddOpts.name,
99					"ref":          skillsCollectionAddOpts.ref,
100					"cachedSkills": len(index.Manifests),
101				})
102			}
103			fmt.Fprintf(cmd.ErrOrStderr(), "Registered collection %q -> %s\n", skillsCollectionAddOpts.name, skillsCollectionAddOpts.ref)
104			fmt.Fprintf(cmd.ErrOrStderr(), "  cached %d skill(s)\n", len(index.Manifests))
105			return nil
106		},
107	}
108	
109	func init() {
110		skillsCollectionAddCmd.Flags().StringVar(
111			&skillsCollectionAddOpts.name, "name", "",
112			"Local name for the collection",
113		)
114		skillsCollectionAddCmd.Flags().StringVar(
115			&skillsCollectionAddOpts.ref, "ref", "",
116			"OCI reference of the collection",
117		)
118		skillsCollectionAddCmd.Flags().StringVarP(&skillsCollectionAddOpts.output, "output", "o", "plain", "output format: plain or json")
119		skillsCollectionCmd.AddCommand(skillsCollectionAddCmd)
120	}
