package main

import (
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"

	"github.com/integrio-intropy/intropy-cli/internal/blueprint"
	"github.com/integrio-intropy/intropy-cli/internal/skill"
	"github.com/integrio-intropy/intropy-cli/internal/skill/oci"
	"golang.org/x/term"
)

// The official Intropy skills collection offered by `int create`.
const (
	defaultSkillsCollectionAlias = "intropy"
	defaultSkillsCollectionRef   = "ghcr.io/integrio-intropy/skills/collection:latest"
)

// maybeInstallSkills asks whether to install the default skills collection
// into the freshly scaffolded integration and, on yes, does the equivalent of
// `skills collection add` plus `skills add` for every skill in the collection.
// The prompt is skipped entirely (nothing is installed) with --no-input or
// when stdin is not a terminal, mirroring the blueprint value prompts.
func maybeInstallSkills(ctx context.Context, in io.Reader, errW io.Writer, noInput bool, outputDir string) error {
	if noInput {
		return nil
	}
	f, ok := in.(*os.File)
	if !ok || !term.IsTerminal(int(f.Fd())) {
		return nil
	}

	install, err := confirmInstallSkills(in, errW)
	if err != nil || !install {
		return err
	}

	project, err := skillProjectAt(outputDir)
	if err != nil {
		return err
	}
	client, err := oci.NewClient()
	if err != nil {
		return err
	}
	installer := skill.NewInstaller(client, skill.NewTarGzExtractor(), project)
	adder := skill.NewAdder(client, installer, project)

	entries, err := skill.NewCollectionInstaller(client, adder, project).
		InstallAll(ctx, defaultSkillsCollectionAlias, defaultSkillsCollectionRef)
	if err != nil {
		return err
	}
	for _, e := range entries {
		fmt.Fprintf(errW, "  installed %s @ %s -> %s\n", e.Name, e.Source.Tag, e.Path)
	}
	fmt.Fprintf(errW, "installed %d skill(s) from %s\n", len(entries), defaultSkillsCollectionRef)
	return nil
}

// confirmInstallSkills renders a [Y/n] prompt (default yes) and reads the
// answer. EOF counts as a decline, not an error.
func confirmInstallSkills(in io.Reader, out io.Writer) (bool, error) {
	v, err := blueprint.NewStdinPrompter(in, out).Prompt(blueprint.FieldSpec{
		Name:    "install-skills",
		Title:   "Install agent skills into .agents/skills?",
		Type:    "boolean",
		Default: true,
	})
	if errors.Is(err, io.EOF) {
		return false, nil
	}
	if err != nil {
		return false, err
	}
	b, ok := v.(bool)
	return ok && b, nil
}

// skillProjectAt returns the skills project rooted exactly at dir, creating an
// empty skills.json there if the blueprint didn't ship one. Unlike
// resolveOrBootstrapProject it never walks up: the scaffolded integration is
// its own skills project even when created inside a larger repo.
func skillProjectAt(dir string) (*skill.Project, error) {
	abs, err := filepath.Abs(dir)
	if err != nil {
		return nil, err
	}
	p := &skill.Project{Root: abs}
	if _, err := os.Stat(p.ManifestPath()); err == nil {
		return p, nil
	} else if !os.IsNotExist(err) {
		return nil, err
	}
	if err := p.SaveManifest(&skill.Manifest{Skills: []skill.ManifestEntry{}}); err != nil {
		return nil, fmt.Errorf("bootstrap skills.json: %w", err)
	}
	return p, nil
}

